SELECT p.id AS position_id, s.id, s.generated_at, s.latest_price, s.decision FROM paper_position p JOIN trade_signal e ON e.id = p.signal_id JOIN trade_signal s ON s.symbol = e.symbol AND s.interval_code = '1m' AND s.generated_at BETWEEN e.generated_at - INTERVAL 30 MINUTE AND e.generated_at WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id, s.generated_at DESC LIMIT 200